import{_ as t,o,c as a,a2 as n}from"./chunks/framework.k9nOhppk.js";const g=JSON.parse('{"title":"How Eyelang works","description":"","frontmatter":{"title":"How Eyelang works"},"headers":[],"relativePath":"internals/architecture.md","filePath":"internals/architecture.md","lastUpdated":1791864160000}'),s={name:"internals/architecture.md"};function r(d,e,c,i,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-eyelang-works" tabindex="-1">How Eyelang works <a class="header-anchor" href="#how-eyelang-works" aria-label="Permalink to &quot;How Eyelang works&quot;">​</a></h1><p>This page is a map of the repository for someone who uses Eyelang or wants to change it, and hasn&#39;t read the code. It says what each part does, what it takes and gives, and which file to open first. It describes <code>dev</code> as of 2026-10-13. For what is built and what isn&#39;t, see <a href="/reference/status">What runs today</a>.</p><p>A few words first. An <strong>entity</strong> is a piece of shared state with an owner: its data changes only through its own methods. A <strong>job</strong> is a function that can wait for days. Each <strong>step</strong> of a job is a call marked <code>!</code>, whose result is recorded. A <strong>run</strong> is one execution of a job. A <strong>contract</strong> describes another service&#39;s operations and types. A <strong>view</strong> is a named query over entities that stays up to date. The <a href="/reference/language/#glossary">glossary</a> has the rest.</p><nav class="table-of-contents"><ul><li><a href="#_1-the-pipeline-on-one-screen">1. The pipeline on one screen</a></li><li><a href="#_2-the-runtime">2. The runtime</a></li><li><a href="#_3-the-store-and-the-journal">3. The store and the journal</a></li><li><a href="#_4-boundaries">4. Boundaries</a></li><li><a href="#_5-tools-on-the-same-front-end">5. Tools on the same front end</a></li><li><a href="#_6-how-a-language-change-flows">6. How a language change flows</a></li><li><a href="#_7-what-is-generated-from-what">7. What is generated from what</a></li><li><a href="#_8-how-work-is-coordinated">8. How work is coordinated</a></li></ul></nav><h2 id="_1-the-pipeline-on-one-screen" tabindex="-1">1. The pipeline on one screen <a class="header-anchor" href="#_1-the-pipeline-on-one-screen" aria-label="Permalink to &quot;1. The pipeline on one screen&quot;">​</a></h2><p>Every command starts the same way: read the source, check it, and turn it into the resolved IR. From there, a program either runs in the interpreter or is compiled to C.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  .eye files + eye.toml</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>  syntax/    lexer → lossless parser → syntax tree ──────────► formatter (eye fmt)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>  check/     load modules, resolve names, infer types,</span></span>
<span class="line"><span>          │  check matches and effects</span></span>
<span class="line"><span>          │  (adds prelude.eye and runtime/store.eye, and std/ modules on import)</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>  ir/        the resolved, typed program                       (eye check --ir)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>     ┌────┴───────────────────────┐</span></span>
<span class="line"><span>     ▼                            ▼</span></span>
<span class="line"><span>  interp/                      lir/    monomorphic functions in blocks  (eye check --lir)</span></span>
<span class="line"><span>  reference interpreter           │</span></span>
<span class="line"><span>  and runtime                     ▼</span></span>
<span class="line"><span>  (eye run, eye test,          cgen/   C11, plus the runtime written in C</span></span>
<span class="line"><span>   eye repl)                      │</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>                               zig (internal/zig) ──► native binary (eye build)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Stage</th><th>Takes</th><th>Gives</th><th>Open first</th></tr></thead><tbody><tr><td><code>syntax/</code></td><td>a file&#39;s bytes</td><td>tokens (<code>syntax.Lex</code>), a lossless tree (<code>syntax.Parse</code>) that keeps every space and comment, syntax errors, formatted text (<code>syntax.Format</code>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/syntax/parser.go" target="_blank" rel="noreferrer"><code>syntax/parser.go</code></a>, then <code>parse_decl.go</code>, <code>parse_expr.go</code>, <code>parse_stmt.go</code>, <code>parse_type.go</code></td></tr><tr><td><code>check/</code></td><td>a program&#39;s directory</td><td>an <code>*ir.Program</code> and a list of diagnostics (<code>check.Program(dir)</code>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check.go" target="_blank" rel="noreferrer"><code>check/check.go</code></a>; types in <code>infer.go</code>, matches in <code>exhaust.go</code>, effects in <code>effects.go</code>, lowering in <code>lower.go</code></td></tr><tr><td><code>ir/</code></td><td>(built by <code>check/</code>)</td><td>a tree where every name points at its declaration, every expression has its type, and pipes and string interpolation are plain calls</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/ir/ir.go" target="_blank" rel="noreferrer"><code>ir/ir.go</code></a>; the built-in functions are declared in <a href="https://github.com/ruxxzebre/eyelang/blob/dev/ir/builtin.eye" target="_blank" rel="noreferrer"><code>ir/builtin.eye</code></a></td></tr><tr><td><code>interp/</code></td><td>an <code>*ir.Program</code></td><td>the program running: <code>main</code>, then its jobs (<code>interp.Run</code>), or its tests (<code>interp.RunTests</code>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/eval.go" target="_blank" rel="noreferrer"><code>interp/eval.go</code></a> for expressions, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/runtime.go" target="_blank" rel="noreferrer"><code>interp/runtime.go</code></a> for entities and runs</td></tr><tr><td><code>lir/</code></td><td>an <code>*ir.Program</code></td><td>the low IR: one function per generic function and set of types it is used at, each a list of blocks of named values (<code>lir.Lower</code>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/lir/lir.go" target="_blank" rel="noreferrer"><code>lir/lir.go</code></a></td></tr><tr><td><code>cgen/</code></td><td>the low IR</td><td>C11 files with <code>#line</code> directives pointing at <code>.eye</code> lines, compiled by the pinned zig (<code>cgen.Generate</code>, <code>cgen.Build</code>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/cgen.go" target="_blank" rel="noreferrer"><code>cgen/cgen.go</code></a>, and the C runtime in <a href="https://github.com/ruxxzebre/eyelang/tree/dev/cgen/runtime" target="_blank" rel="noreferrer"><code>cgen/runtime/</code></a>, starting at <code>eye.h</code></td></tr></tbody></table><p>Three things to know about this picture:</p><ul><li><strong>The grammar is defined twice.</strong> <a href="https://github.com/ruxxzebre/eyelang/blob/dev/tree-sitter-eyelang/grammar.js" target="_blank" rel="noreferrer"><code>tree-sitter-eyelang/grammar.js</code></a> is the definition of the syntax. The parser in <code>syntax/</code> is written by hand, because it gives better error messages. Tree-sitter runs only in tests, as an oracle: the two parsers must build the same tree for every file in the conformance suite.</li><li><strong>The standard library is Eyelang.</strong> <code>check/prelude.eye</code> and the store in <code>check/runtime/store.eye</code> are checked with every program, and the modules in <code>check/std/</code> (<code>ai</code>, <code>approvals</code>, <code>fs</code>, <code>http</code>, <code>process</code>, <code>random</code>, <code>regex</code>) with each program that imports them.</li><li><strong>Native code covers the core language only.</strong> <code>eye build</code> compiles functions, records, variants, <code>match</code>, loops, closures, strings, collections, traits and tests. Entities, jobs, views and contracts run in the interpreter (<code>eye run</code>) until ROADMAP task 7.6, when the Go runner hosts compiled code. The design is in <a href="/internals/compilation">Compiling Eyelang</a>.</li></ul><h2 id="_2-the-runtime" tabindex="-1">2. The runtime <a class="header-anchor" href="#_2-the-runtime" aria-label="Permalink to &quot;2. The runtime&quot;">​</a></h2><p>The runtime is the part of <code>interp/</code> that keeps what a program holds beyond its values: entities, runs, views, the clock and the fakes of other services. The language rules are in the reference&#39;s <a href="/reference/language/entities">Entities</a>, <a href="/reference/language/jobs-and-waiting">Jobs and waiting</a> and <a href="/reference/language/views-and-triggers">Views and triggers</a>; the guide&#39;s <a href="/guide/jobs-and-waiting">Jobs and waiting</a> explains them with examples.</p><p><strong>Transactions.</strong> An entity method runs as a transaction: one writer per entity at a time, all or nothing. When a method calls other entities, the whole call tree commits or rolls back together. A served operation is one transaction too. Jobs started and events published inside a transaction happen only if it commits. See <code>txn</code>, <code>callEntity</code> and <code>commit</code> in <code>interp/runtime.go</code>.</p><p><strong>Runs and steps.</strong> Starting a job makes a run. Each <code>!</code> call in the job is a step: it runs once, and its result is saved in the run&#39;s record. An entity call from a job commits in the same store transaction as the step that records it, so it happens exactly once. A job reads entities only through steps (<code>w.read!()</code>, <code>view.read!()</code>), so a resumed run sees what it saw before.</p><p><strong>Checkpoints and replay.</strong> At the start of each statement in a job&#39;s body, a run that has taken steps since its last checkpoint saves a new one: its variables, the statement it is at, and where each loop around it is. The steps before it are dropped. When a run wakes, it restores the checkpoint and replays only the steps since, each returning its recorded result instead of calling again. So a job that loops for weeks keeps a record the size of its variables. A checkpoint names its statement by a hash of the typed IR, so a run whose code changed under it faults instead of resuming in the wrong place. Open <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/checkpoint.go" target="_blank" rel="noreferrer"><code>interp/checkpoint.go</code></a> and <code>interp/jobs.go</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  remind(&quot;ann&quot;) starts                                       run 1</span></span>
<span class="line"><span>    step 1  notify.send!(…)                 result recorded; entity calls commit with it</span></span>
<span class="line"><span>            checkpoint: variables and place saved, step 1 dropped</span></span>
<span class="line"><span>    step 2  next!(answered, within: 3 days)</span></span>
<span class="line"><span>            the run waits: record on disk, about 140 bytes in memory</span></span>
<span class="line"><span>    … three days pass, or advance(3 days) in a test …</span></span>
<span class="line"><span>            wake: record read back, checkpoint restored; step 2 gives None</span></span>
<span class="line"><span>    step 3  notify.send!(…)                 the reminder, recorded</span></span>
<span class="line"><span>    end     outcome Completed(…) saved</span></span></code></pre></div><p><strong>Waiting.</strong> <code>sleep!</code>, <code>next!</code> (an event), <code>approval!</code> (a person), <code>run.join!()</code> and the other waiting calls park the run. A parked run is a handle in memory (its number, job, when it wakes and what event wakes it, about 140 bytes) and a record on disk. See <code>interp/handles.go</code>, <code>sleep</code> in <code>interp/jobs.go</code>, and <code>interp/waits.go</code> for joining runs and locks.</p><p><strong>Views and events.</strong> When a transaction commits, the runtime updates the views over the entities it changed (<code>updateViews</code> in <code>interp/runtime.go</code>). <code>@on(enters(view))</code> starts a run for each entity that begins to match, <code>@on(leaves(view))</code> for each that stops. Events are published on commit, or as a job&#39;s step; <code>next!</code> waits for one.</p><p><strong>Schedules.</strong> <code>@on(daily(07:40, in: zone))</code>, <code>weekdays(…)</code>, <code>cron(…)</code> and <code>every(…)</code> start runs on a time zone&#39;s clock, with rules for daylight-saving gaps and overlaps (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/schedule.go" target="_blank" rel="noreferrer"><code>interp/schedule.go</code></a>). Each firing is saved with the run it starts, so a restart neither repeats nor skips one.</p><p><strong>The clock and fakes.</strong> Under <code>eye run</code> the runtime&#39;s clock follows real time. In a test it starts at 2026-01-01 00:00 UTC, or where <code>with clock(…)</code> puts it, and moves only when the test calls <code>advance(…)</code>; runs that wake on the way run in order before <code>advance</code> returns. The playground uses a third kind, a virtual clock (<code>VirtualClock</code> in <code>interp/serve.go</code>) that skips ahead instead of waiting. <code>with fakes(notify, from: &quot;recordings/&quot;)</code> answers a contract&#39;s calls from recorded exchanges in JSON (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/fakes.go" target="_blank" rel="noreferrer"><code>interp/fakes.go</code></a>), checked against the contract when they load. Tests are deterministic in the clock, the store and random numbers; a test reaches the real network only if it calls a service without fakes. The guide&#39;s <a href="/guide/testing">Testing</a> page shows both.</p><h2 id="_3-the-store-and-the-journal" tabindex="-1">3. The store and the journal <a class="header-anchor" href="#_3-the-store-and-the-journal" aria-label="Permalink to &quot;3. The store and the journal&quot;">​</a></h2><p>Everything a program keeps goes through one interface, <code>Store</code> in <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/store.go" target="_blank" rel="noreferrer"><code>interp/store.go</code></a>: load and save entity rows, run records, events and meta keys, one <code>Commit</code> per transaction.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  runtime (interp/runtime.go)</span></span>
<span class="line"><span>      │  Store interface (interp/store.go)</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>  MemoryStore ─ written in Eyelang: check/runtime/store.eye</span></span>
<span class="line"><span>      │         an immutable value; each commit is a pure function to the next one</span></span>
<span class="line"><span>      │         used alone by tests, the REPL and eye run --memory</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├── wrapped by Journal (interp/journal.go)    ──► DIR/.eye/journal   (eye run&#39;s default)</span></span>
<span class="line"><span>      └── wrapped by Postgres (interp/postgres.go)  ──► --store postgres://…  or $EYE_STORE</span></span></code></pre></div><ul><li><strong>The in-memory store is written in Eyelang.</strong> <code>MemoryStore</code> in <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/runtime/store.eye" target="_blank" rel="noreferrer"><code>check/runtime/store.eye</code></a> is part of every program and is interpreted like any other code. It doesn&#39;t survive a restart on its own.</li><li><strong>The journal</strong> is a file for one machine. It appends each commit, and syncs it to disk before anything outside the runner can see it: before a service call, output, an answered request or a wait. One sync covers every commit since the last. When it opens, and when the file grows past four times the live data, it is rewritten as a snapshot, so it grows with the state, not the history. A line cut short by a crash is dropped.</li><li><strong>The Postgres store</strong> keeps the same state in a database, so it survives the loss of the machine. Each commit is one SQL transaction. One runner writes a store at a time, held by an advisory lock; one database can hold several programs, one per schema.</li><li><strong>Waiting runs leave memory.</strong> Both durable stores keep the record of a run that waits or has ended on disk, and read it back when it wakes.</li><li><strong><code>eye runs</code></strong> reads the journal or the database without changing it, so it works while <code>eye run</code> runs. It lists each run&#39;s status, what it waits for, and its steps; <code>eye runs DIR 12 3</code> shows run 12&#39;s third step whole. <code>eye approve</code> and <code>eye decline</code> answer an <code>approval!</code> by writing a file to <code>DIR/.eye/inbox</code>, which the runner reads (<code>interp/inbox.go</code>).</li></ul><p>The guide&#39;s <a href="/guide/running">Running in production</a> page covers flags, restarts and stopping.</p><h2 id="_4-boundaries" tabindex="-1">4. Boundaries <a class="header-anchor" href="#_4-boundaries" aria-label="Permalink to &quot;4. Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>What it does</th><th>Where</th></tr></thead><tbody><tr><td>Contracts over HTTP</td><td>A contract&#39;s values go as JSON, and its operations as HTTP requests, by one set of rules. The interpreter follows them when it calls a service and when <code>eye run</code> serves a contract.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/wire/wire.go" target="_blank" rel="noreferrer"><code>internal/wire</code></a>; calls in <code>interp/services.go</code> (<code>callHTTP</code>), serving in <code>interp/listen.go</code></td></tr><tr><td>Generated clients</td><td><code>eye gen go</code> and <code>eye gen ts</code> write types, a client and a server stub for each contract, from the same rules, so the two sides can&#39;t drift. <code>eye gen policy</code> writes Kubernetes network policies.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/codegen/codegen.go" target="_blank" rel="noreferrer"><code>internal/codegen</code></a>, golden files in <code>internal/codegen/testdata</code>; <code>internal/netpolicy</code></td></tr><tr><td>Embedding in Go</td><td>A Go program loads an Eyelang program, registers the functions its <code>@host</code> declarations name, and runs it or its tests.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/host/host.go" target="_blank" rel="noreferrer"><code>host/host.go</code></a></td></tr><tr><td>Calling C</td><td><code>@library</code> functions are loaded from shared libraries at run time, without cgo. On Linux this makes a binary dynamic, so the released <code>eye</code> has it only with <code>-tags clib</code>.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/ffi/ffi.go" target="_blank" rel="noreferrer"><code>internal/ffi</code></a>, used through <code>host/clib</code></td></tr></tbody></table><p>The guide&#39;s <a href="/guide/contracts">Talking to other services</a> page shows contracts from the user&#39;s side, and the reference&#39;s <a href="/reference/language/calling-c-and-go">Calling C and Go</a> gives the rules.</p><h2 id="_5-tools-on-the-same-front-end" tabindex="-1">5. Tools on the same front end <a class="header-anchor" href="#_5-tools-on-the-same-front-end" aria-label="Permalink to &quot;5. Tools on the same front end&quot;">​</a></h2><p>Every tool reads code through <code>syntax/</code> and <code>check/</code>, so they agree with the compiler by construction.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th><th>Where</th></tr></thead><tbody><tr><td><code>eye fmt</code></td><td>Formats source. It has no options, and it refuses a file with syntax errors.</td><td><code>syntax/format.go</code>; cases in <code>testdata/fmt</code></td></tr><tr><td><code>eye lsp</code></td><td>The language server: completion, definitions, references, hover, semantic highlighting. <code>eye lsp --definition FILE:LINE:COL</code> answers one request from the shell.</td><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/internal/lsp" target="_blank" rel="noreferrer"><code>internal/lsp</code></a>; the VS Code client in <code>editors/vscode</code></td></tr><tr><td><code>eye doc</code></td><td>Writes the API reference as Markdown from <code>##</code> comments.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/apidoc/apidoc.go" target="_blank" rel="noreferrer"><code>internal/apidoc</code></a></td></tr><tr><td>Playground</td><td>The checker, interpreter, formatter and language server built for WebAssembly, run in the browser on a virtual clock.</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/playground/playground.go" target="_blank" rel="noreferrer"><code>internal/playground</code></a>, <code>cmd/eye-wasm</code>; <code>task playground</code> builds it into <code>docs/public/wasm</code></td></tr><tr><td><code>eye repl</code></td><td>An interactive session for expressions, declarations and jobs.</td><td><code>cmd/eye/repl.go</code>, line editor in <code>repl/</code></td></tr></tbody></table><p>All commands live in <a href="https://github.com/ruxxzebre/eyelang/tree/dev/cmd/eye" target="_blank" rel="noreferrer"><code>cmd/eye</code></a>, one file each; <a href="/reference/cli">The eye command</a> lists them.</p><h2 id="_6-how-a-language-change-flows" tabindex="-1">6. How a language change flows <a class="header-anchor" href="#_6-how-a-language-change-flows" aria-label="Permalink to &quot;6. How a language change flows&quot;">​</a></h2><p>A change to the language touches every stage, in this order. CLAUDE.md is the source for these rules.</p><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Files</th><th>Command</th></tr></thead><tbody><tr><td>1</td><td>Write the rule and an example in the spec. A decision gets a row in the decision log (§2); an unsettled idea goes to the open questions (§24).</td><td><code>SPECS.md</code></td><td></td></tr><tr><td>2</td><td>Change the grammar. Newlines, braces and strings also need the scanner.</td><td><code>tree-sitter-eyelang/grammar.js</code>, <code>src/scanner.c</code></td><td><code>cd tree-sitter-eyelang &amp;&amp; tree-sitter test -i &#39;Name&#39;</code></td></tr><tr><td>3</td><td>Change the hand-written parser, and the formatter if layout changes.</td><td><code>syntax/</code></td><td><code>go test ./syntax -run TestFormat</code></td></tr><tr><td>4</td><td>Add tests: a valid file per construct, an invalid file per error, and corpus cases.</td><td><code>testdata/syntax/valid</code>, <code>testdata/syntax/invalid</code>, <code>tree-sitter-eyelang/test/corpus</code></td><td><code>go test ./syntax -run TestSyntaxErrors -update</code>, then read the diff of <code>diagnostics.txt</code></td></tr><tr><td>5</td><td>Regenerate, then check both parsers agree.</td><td></td><td><code>task generate</code>, <code>task conformance</code>, <code>task fuzz</code></td></tr><tr><td>6</td><td>Teach the checker; test its messages.</td><td><code>check/</code>, tests in <code>check/*_test.go</code></td><td><code>go test ./check</code></td></tr><tr><td>7</td><td>Teach the interpreter; add a program whose tests use the feature.</td><td><code>interp/</code>, <code>testdata/programs/&lt;area&gt;</code></td><td><code>go run ./cmd/eye test testdata/programs/core</code>, <code>go test ./interp</code></td></tr><tr><td>8</td><td>Lower it for native code, or make <code>eye build</code> refuse it with a clear error.</td><td><code>lir/</code>, <code>cgen/</code>, <code>cgen/testdata</code>, <code>testdata/ir</code></td><td><code>go test ./cgen</code>, <code>go test ./cmd/eye -run TestCheckIR -update</code></td></tr><tr><td>9</td><td>Editor support.</td><td><code>internal/lsp</code>, <code>editors/vscode/syntaxes</code></td><td><code>go test ./internal/lsp</code>, <code>task vscode</code></td></tr><tr><td>10</td><td>Docs and bookkeeping: the guide, the status page, ROADMAP.md&#39;s &quot;What&#39;s next&quot;.</td><td><code>docs/guide</code>, <code>docs/reference/status.md</code>, <code>ROADMAP.md</code></td><td><code>task quick</code> while working, <code>task check</code> before pushing</td></tr></tbody></table><p><code>task quick</code> builds <code>eye</code>, tests the checker, interpreter and parser, then checks and tests the lab&#39;s programs in <code>testdata/lab</code>, in seconds. <code>task check</code> runs everything CI runs.</p><p>When the language changes under existing code, the fix is a rewrite in <code>eye fix</code>, not a compatibility rule.</p><h2 id="_7-what-is-generated-from-what" tabindex="-1">7. What is generated from what <a class="header-anchor" href="#_7-what-is-generated-from-what" aria-label="Permalink to &quot;7. What is generated from what&quot;">​</a></h2><p>Never edit a generated file. Change its source and run the command.</p><table tabindex="0"><thead><tr><th>Generated</th><th>From</th><th>Command</th></tr></thead><tbody><tr><td><code>tree-sitter-eyelang/src/</code> (except <code>scanner.c</code>)</td><td><code>grammar.js</code></td><td><code>task generate</code></td></tr><tr><td><code>syntax/kind_gen.go</code>, <code>syntax/view_gen.go</code></td><td>the grammar&#39;s <code>node-types.json</code>, by <code>syntax/gen</code></td><td><code>task generate</code></td></tr><tr><td><code>testdata/syntax/valid/spec-*.eye</code>, <code>testdata/programs/tour/tour.eye</code></td><td>the examples in <code>SPECS.md</code>, by <code>tools/specexamples</code></td><td><code>task generate</code></td></tr><tr><td><code>docs/reference/language/</code>, <code>docs/design/</code>, <code>docs/.vitepress/spec-sidebar.json</code></td><td><code>SPECS.md</code>, by <code>tools/specpages</code></td><td><code>task generate</code></td></tr><tr><td><code>docs/reference/api/</code></td><td><code>##</code> comments in the standard library, by <code>eye doc</code></td><td><code>task generate</code></td></tr><tr><td><code>docs/reference/cli.md</code></td><td><code>eye help</code>, by <code>tools/clidoc</code></td><td><code>task generate</code></td></tr><tr><td><code>docs/internals/benchmarks.md</code>, <code>testdata/bench/results.json</code></td><td>the programs in <code>testdata/bench</code>, by <code>tools/bench</code></td><td><code>go run ./tools/bench --write</code></td></tr><tr><td><code>docs/public/wasm/</code> (not in git)</td><td><code>cmd/eye-wasm</code></td><td><code>task playground</code></td></tr><tr><td><code>testdata/syntax/invalid/diagnostics.txt</code></td><td>the parser&#39;s messages</td><td><code>go test ./syntax -run TestSyntaxErrors -update</code></td></tr><tr><td><code>testdata/ir/*/ir.golden</code>, <code>lir.golden</code></td><td><code>eye check --ir</code> and <code>--lir</code></td><td><code>go test ./cmd/eye -run TestCheckIR -update</code></td></tr></tbody></table><p><code>task generated</code> fails when a generated file in git doesn&#39;t match its source; <code>task check</code> runs it.</p><h2 id="_8-how-work-is-coordinated" tabindex="-1">8. How work is coordinated <a class="header-anchor" href="#_8-how-work-is-coordinated" aria-label="Permalink to &quot;8. How work is coordinated&quot;">​</a></h2><p>Several people and coding agents work on the repository at once.</p><ul><li><strong><code>task next</code></strong> says what to do next, from what is true now: the last release and what landed since, ROADMAP.md&#39;s &quot;What&#39;s next&quot;, the open issues, the gaps in <a href="/reference/status">What runs today</a>, and what each worktree holds that <code>dev</code> doesn&#39;t. Start every session with it.</li><li><strong><code>task claim -- WHO PATH…</code></strong> records which paths a session is changing, in the repository&#39;s git config, which every worktree shares. <code>task next</code> lists the claims. Leave others&#39; claims alone or ask their owner, and give yours back with <code>task claim -- --release WHO</code> once the work is merged.</li><li><strong>Worktrees.</strong> Each session works in a git worktree of its own, unless it is the one merging into <code>dev</code>. <code>git worktree list</code> shows them.</li><li><strong>Branches.</strong> Development and releases happen on <code>dev</code>; <code>main</code> stays at Eyelang 1 for now. Commits say <code>Closes #N</code> for the ROADMAP task they finish, and the <code>Close issues</code> workflow closes the issue when the commit reaches <code>dev</code>.</li><li><strong>CI</strong> (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/.github/workflows/ci.yml" target="_blank" rel="noreferrer"><code>.github/workflows/ci.yml</code></a>) runs <code>task check</code> on every push and pull request to <code>dev</code> and <code>main</code>, with a Postgres server and Docker for the tests that need them. A local <code>task check</code> skips those tests, so watch the run after pushing.</li></ul>`,44)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
